import sys,json,collections
from pathlib import Path
r=Path(__file__).resolve().parent;sys.path.insert(0,str(r))
from assess_surface_transaction470 import sha,terminal_receipt,owned_rows
c=max((r/'cases').glob('curved481_saved_surface_corrections_serial_*'),key=lambda p:p.stat().st_mtime);s=json.loads((c/'status.json').read_text());assert s['state']=='terminal' and s['exit_code']==0 and s['pins_verified']
pins=json.loads((c/'pins.json').read_text());assert all(sha(p)==h for p,h in pins.items());t=terminal_receipt(c);(c/'terminal_handles_actual.json').write_text(json.dumps(t,indent=2)+'\n')
v=[json.loads(l) for l in (c/'actual_bl_cavity_planning.jsonl').read_text().splitlines()];trials=[x for x in v if x['stage']=='saved_correction_trial'];assert len(trials)==24 and [x['slot'] for x in trials]==list(range(1,25))
counts=collections.Counter(x['context'] for x in trials);assert set(counts.values())=={8} and len(counts)==3
result=[x for x in v if x['stage']=='saved_correction_result'];publication=[x for x in v if x['stage']=='saved_correction_publication'];assert len(result)==len(publication)==1 and result[0]['published'] and result[0]['contexts_completed']==3
native=[x for x in trials if x['private_feasible'] and x['context']!='clean_control'];assert len(native)==9
winner=max(native,key=lambda x:x['old_geometry_excess']-x['new_geometry_excess']);assert publication[0]['context']==winner['context'] and publication[0]['operator']==winner['operator']
receipt=json.loads((r/'surface_comparison478_inputs.json').read_text());source=Path(receipt['owned']['path']);assert sha(source)==receipt['owned']['sha256'];assert sha(c/'correction_unchanged_owned.bin')==sha(source)
a=dict(owned_rows(source));b=dict(owned_rows(c/'trajectory_working_owned.bin'));removed=set(a)-set(b);added=set(b)-set(a);assert len(removed)==winner['old_cells'] and len(added)==winner['new_cells'];assert all(a[k]==b[k] for k in set(a)&set(b))
report=dict(case=str(c),status=s,pins_verified=len(pins),all_actual_handles_terminal=True,planned_context_slots=dict(counts),constructor_calls=len(trials),active_admissible_candidates=len(native),trials=trials,winner=winner,publication=publication[0],result=result[0],working_cells=len(b),removed_cells=len(removed),added_cells=len(added),untouched_cells=len(set(a)&set(b)),untouched_rows_bitidentical=True,original476_input_unchanged=True,working_owned_sha256=sha(c/'trajectory_working_owned.bin'),working_parameters_sha256=sha(c/'trajectory_working_parameters.bin'),geometry_excess_reduction_fraction=1-winner['new_geometry_excess']/winner['old_geometry_excess'],production_qualified=False,goal_complete=False,limitations=['Overall focused53case qualification failed a distant-body resource query.','Chosen candidate reduces upper-bound geometry excess but increases bad-cell count6to7; no geometry closure or demonstrated net bad-count gain.','q/J remain observational and unchanged15to15each on published patch.','Strict first height fails; provisional checks and passing-height preservation pass. No first-row readiness.','SurfacePlanning edge lengths are endpoint/strip guidance, not exact composed3D edge quadrature.','Serial publication does not establish new MPI capability.','More geometry work than478 is not a computational-efficiency gain; wrapper times are contention/setup-sensitive.'])
(r/'saved_surface_corrections481_assessment.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:report[k] for k in ['pins_verified','active_admissible_candidates','working_cells','removed_cells','added_cells','untouched_cells','geometry_excess_reduction_fraction']}))
